#include "atom-rknn_api.h"
#include <cstdio>
#include <cstdlib>
#include <vector>
#include <chrono>
int main(int argc,char**argv){if(argc!=2)return 2;FILE*f=fopen(argv[1],"rb");if(!f)return 2;fseek(f,0,SEEK_END);long size=ftell(f);rewind(f);std::vector<unsigned char> model(size);fread(model.data(),1,size,f);fclose(f);rknn_context ctx=0;int ret=rknn_init(&ctx,model.data(),size,0,nullptr);if(ret){printf("init failed %d\n",ret);return 1;}rknn_sdk_version sdk={};rknn_query(ctx,RKNN_QUERY_SDK_VERSION,&sdk,sizeof(sdk));printf("SDK %s / driver %s\n",sdk.api_version,sdk.drv_version);rknn_input_output_num io={};if(rknn_query(ctx,RKNN_QUERY_IN_OUT_NUM,&io,sizeof(io))||io.n_input!=1){rknn_destroy(ctx);return 1;}rknn_tensor_attr attr={};rknn_query(ctx,RKNN_QUERY_INPUT_ATTR,&attr,sizeof(attr));printf("input elements %u, outputs %u\n",attr.n_elems,io.n_output);std::vector<unsigned char> input(attr.n_elems,128);rknn_input in={};in.index=0;in.buf=input.data();in.size=input.size();in.type=RKNN_TENSOR_UINT8;in.fmt=RKNN_TENSOR_NHWC;std::vector<rknn_output> out(io.n_output);auto start=std::chrono::steady_clock::now();for(int i=0;i<30;i++){ret=rknn_inputs_set(ctx,1,&in);if(!ret)ret=rknn_run(ctx,nullptr);for(unsigned j=0;j<io.n_output;j++){out[j]={};out[j].index=j;out[j].want_float=1;}if(!ret)ret=rknn_outputs_get(ctx,io.n_output,out.data(),nullptr);if(ret){printf("inference failed %d\n",ret);rknn_destroy(ctx);return 1;}if(i==0)printf("output[0] bytes %u, first float %f\n",out[0].size,((float*)out[0].buf)[0]);rknn_outputs_release(ctx,io.n_output,out.data());}double ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count();printf("30 NPU inference cycles %.2fms, average %.2fms; synthetic input, no accuracy claim\n",ms,ms/30);rknn_destroy(ctx);return 0;}
